use std::{env,fs,path::PathBuf};fn main(){println!("cargo::rerun-if-changed=values.txt");let mut v:Vec<_>=fs::read_to_string("values.txt").unwrap().lines().map(str::to_owned).collect();v.sort();let body=format!("pub const VALUES:&[&str]=&[{}];\n",v.iter().map(|s|format!("\"{s}\"")).collect::<Vec<_>>().join(","));fs::write(PathBuf::from(env::var("OUT_DIR").unwrap()).join("generated.rs"),body).unwrap();}
